"""Build the relocation-free JSC hook and its generated byte arrays."""
import pathlib
import subprocess
import json
import struct

root = pathlib.Path(__file__).resolve().parents[1]
source = root / "src"
folder = root / "build/jsc-hook"
folder.mkdir(parents=True, exist_ok=True)
(folder / "jsc_patch_text.h").write_text("static const char jsc_patch_script[]=" + json.dumps((source / "jsc_patch.js").read_text()) + ";\n")
obj = folder / "jsc-hook.o"
elf = folder / "jsc-hook-code.elf"
binary = folder / "jsc-hook.bin"
constants = folder / "jsc-hook-constants.bin"
subprocess.run(["cc", "-c", "-O2", "-fPIE", "-fvisibility=hidden", "-fno-builtin",
                "-fno-stack-protector", "-fno-asynchronous-unwind-tables", "-mno-red-zone",
                "-I", str(folder), "-o", str(obj), str(source / "jsc_hook.c")], check=True)
subprocess.run(["ld", "--emit-relocs", "-T", str(source / "jsc_hook.ld"), "-o", str(elf), str(obj)], check=True)
symbols = {line.split()[2]: int(line.split()[0], 16) for line in
           subprocess.check_output(["nm", str(elf)], text=True).splitlines() if len(line.split()) == 3}
constant_base = symbols["jsc_constants"]
# Retain only text-to-constant PC32 fixups. Internal code branches remain
# position independent when the two remote padding regions move separately.
raw = elf.read_bytes()
shoff = struct.unpack_from("<Q", raw, 40)[0]
sections = [struct.unpack_from("<IIQQQQIIQQ", raw, shoff + i*64)
            for i in range(struct.unpack_from("<H", raw, 60)[0])]
fixups = []
for section in sections:
    if section[1] != 4:
        continue
    symtab = sections[section[6]]
    for at in range(section[4], section[4] + section[5], 24):
        offset, info, addend = struct.unpack_from("<QQq", raw, at)
        symbol = struct.unpack_from("<IBBHQQ", raw, symtab[4] + (info >> 32)*24)
        if info & 0xffffffff != 2:
            raise SystemExit("Unexpected hook relocation")
        if sections[symbol[3]][3] == constant_base:
            fixups.append(offset)
subprocess.run(["objcopy", "-O", "binary", "--only-section=.hook", str(elf), str(binary)], check=True)
data = binary.read_bytes()
subprocess.run(["objcopy", "-O", "binary", "--only-section=.constants", str(elf), str(constants)], check=True)
constant_data = constants.read_bytes()
if symbols["jsc_call"] != 0 or len(data) > 0x1000 or len(constant_data)>0x1000:
    raise SystemExit("Unexpected hook entry or size")
lines = ["/* SPDX-License-Identifier: GPL-3.0-or-later */",
         "/* Generated by src/generate_jsc_hook.py. */",
         f"#define JSC_HOOK_CONSTANTS_DELTA 0x{constant_base:x}",
         f"#define JSC_HOOK_STATE_OFFSET {symbols['jsc_state'] - constant_base}",
         "static const unsigned char jsc_hook_blob[]={"]
lines += ["    " + ",".join(f"0x{x:02x}" for x in data[i:i+16]) + "," for i in range(0, len(data), 16)]
lines += ["};", "static const unsigned char jsc_hook_constants[]={"]
lines += ["    " + ",".join(f"0x{x:02x}" for x in constant_data[i:i+16]) + "," for i in range(0, len(constant_data), 16)]
lines += ["};", "static const unsigned jsc_hook_constant_fixups[]={" + ",".join(str(x) for x in fixups) + "};", ""]
(source / "jsc_hook_blob.h").write_text("\n".join(lines))
print(f"JSC hook: {len(data)} code bytes, {len(constant_data)} constant bytes, state +{symbols['jsc_state'] - constant_base:x}")
